<?php foreach($rows as $i=>$item): ?><div class="card card-border-merah produk" data-produk data-kategori="<?= e($item['category']) ?>" data-harga="<?= (int)$item['price'] ?>" data-urutan="<?= $i+1 ?>"><div class="produk-gambar"><?php if($item['badge']): ?><span class="<?= e(badge_class($item['badge'])) ?>"><?= e($item['badge']) ?></span><?php endif; ?><img src="<?= e($item['image_url']??'images/shop-banner.jpg') ?>" alt="<?= e($item['name']) ?>"></div><h4 class="berita-judul"><?= e($item['name']) ?></h4><p class="paragraf-kecil"><?= e($item['description']??'') ?></p><p class="harga"><?= e(rupiah($item['price'])) ?></p><span class="btn btn-merah lebar">Lihat Produk</span></div><?php endforeach; ?><p id="produk-kosong" class="pesan-kosong" hidden>Tidak ada produk yang sesuai dengan filter.</p>
